function showBootError(message){document.getElementById('balance').textContent='—';document.querySelectorAll('#app > header button,#app > nav button').forEach(b=>b.disabled=true);const main=document.getElementById('main');main.innerHTML='<section class="save-recovery"><h1>存档暂时无法打开</h1><p id="load-error"></p><p>已停止游戏写入，保护原有收藏。可重新打开，或使用之前复制的备份恢复。</p><button class="primary" id="retry-load">重新读取</button><textarea id="rescue-backup" rows="7" aria-label="粘贴完整存档备份"></textarea><button class="secondary" id="check-rescue">检查恢复备份</button><div id="rescue-check"></div></section>';document.getElementById('load-error').textContent=message;document.getElementById('retry-load').onclick=()=>location.reload();document.getElementById('check-rescue').onclick=()=>{const target=document.getElementById('rescue-check');try{const b=JSON.parse(document.getElementById('rescue-backup').value),mode=new URLSearchParams(location.search).get('mode')==='starter'?'starter':'standard';if(b.format!=='kanto-backup-1'||b.mode!==mode)throw Error('请粘贴相同模式的完整备份');const state=window.Vault.load({getItem:()=>JSON.stringify(b.state)});target.innerHTML='<p>待恢复 '+state.inventory.length+' 张收藏、'+state.wallet+' 金币。确认后将替换无法打开的原存档。</p><button class="primary" id="confirm-rescue">确认用备份恢复</button>';document.getElementById('confirm-rescue').onclick=async()=>{try{window.Vault.save(state,window.VaultPlatform.storage);await window.VaultPlatform.flush();location.reload();}catch(e){target.textContent='暂时无法写入，请保留备份并重新打开后再试。';}};}catch(e){target.textContent='备份不完整或模式不匹配，请重新粘贴完整备份。';}};}
await window.VaultPlatform.ready;if(window.VaultPlatform.error){showBootError(window.VaultPlatform.error);return;}
