const TRAINER_NAMES={"Antique Dome Fossil":"陈旧的甲壳化石","Antique Helix Fossil":"陈旧的贝壳化石","Antique Old Amber":"陈旧的秘密琥珀","Big Air Balloon":"大气球","Bill's Transfer":"正辉的输送","Cycling Road":"自行车道","Daisy's Help":"奈奈美的帮助","Energy Sticker":"能量贴纸","Erika's Invitation":"莉佳的招待","Giovanni's Charisma":"坂木的领导力","Grabber":"抓换臂","Leftovers":"吃剩的东西","Protective Goggles":"安全护目镜","Rigid Band":"硬硬束带","Switch":"宝可梦交替","Basic Psychic Energy":"基本超能量","Clefairy Doll":"皮皮玩偶","Computer Search":"电脑搜索","Devolution Spray":"退化喷雾","Imposter Professor Oak":"假大木博士","Item Finder":"道具探测器","Lass":"少女","Pokémon Breeder":"宝可梦培育家","Pokémon Trader":"宝可梦交换员","Scoop Up":"收回","Super Energy Removal":"超级能量移除","Defender":"防御强化","Energy Removal":"能量移除","Full Heal":"万灵药","Maintenance":"维修","PlusPower":"力量强化","Pokémon Center":"宝可梦中心","Pokémon Flute":"宝可梦之笛","Pokédex":"宝可梦图鉴","Professor Oak":"大木博士","Revive":"活力碎片","Super Potion":"好伤药","Bill":"正辉","Gust of Wind":"起风","Potion":"伤药","Double Colorless Energy":"双重无色能量","Fighting Energy":"基本斗能量","Fire Energy":"基本火能量","Grass Energy":"基本草能量","Lightning Energy":"基本雷能量","Psychic Energy":"基本超能量","Water Energy":"基本水能量","Darkness Energy":"基本恶能量","Metal Energy":"基本钢能量","Impostor Professor Oak":"假大木博士","Energy Retrieval":"基础能量回收","Poké Ball":"精灵球","Mr. Fuji":"富士老人","Energy Search":"能量搜寻","Gambler":"赌徒","Recycle":"再利用","Mysterious Fossil":"神秘化石"};
const pokemon=c=>{const info=E.cardInfo(c),old=POKEMON.find(p=>p.id===(c.species||info?.dexId?.[0]));return {...(old||{id:0,en:info?.name||'训练家',types:[]}),name:window.TCG_SIMPLIFIED?.[c.cardId]?.name||(old?old.name+(info?.name?.endsWith(' ex')?' ex':''):(TRAINER_NAMES[info?.name]||window.TCG_CHINESE?.[c.cardId]?.name?.split('[')[0]||info?.name||'训练家卡'))};},icon=n=>window.KantoIcons?.icon(n)||'';
async function persist(){try{E.save(S,window.VaultPlatform.storage);await window.VaultPlatform.flush();return true;}catch(e){toast(e.code==='SAVE_CONFLICT'?'另一页已经更新存档，请刷新本页后继续':e.name==='QuotaExceededError'?'存档空间不足，请先复制备份，再整理重复卡。':/[一-鿿]/.test(e.message||'')?e.message:'收藏未能保存，请保持页面打开并重试');return false;}}
function unlock(){try{A.init(S.settings);if(S.settings.music)A.music(true);}catch(e){}}
function toast(t){let el=$('#toast');if(!el){el=document.createElement('div');el.id='toast';el.setAttribute('role','status');}const d=$('#dialog');(d?.open?d:document.body).appendChild(el);el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}

