 bindChaseCards(main,selected);$('#all-chase-cards').onclick=()=>showChaseList(selected);$('#buy').onclick=purchase;$('#pity-info').onclick=showOdds;$('#odds')?.addEventListener('click',showOdds);bindPackManipulation(main);
